 * Shared sort-token constants for the findings surfaces.
 *
 * Two distinct families exist because the two backend resources order rows
 * differently:
 *
 *   Family A — plain findings. `status` and `severity` are Postgres ENUM
 *   columns whose *ascending* order already puts FAIL / critical first, so
 *   these tokens carry NO minus prefix.
 *
 *   Family B — finding-groups. `status`, `severity` and `delta` are
 *   integer-weighted computed columns, so *descending* order is required to
 *   surface FAIL / critical / new results first — these tokens always carry a
 *   minus prefix.
 *
 * This module is deliberately free of any server-only (authentication)
 * imports so action files and client components can share it through the
 * `@/lib` barrel.
 */

// ---------------------------------------------------------------------------
// Family A — plain findings (ascending ENUM order = FAIL / critical first)
// ---------------------------------------------------------------------------

/** FAIL results first. Ascending ENUM order — no minus prefix. */
export const FINDINGS_FAIL_FIRST = "status";
/** Highest severity first. Ascending ENUM order — no minus prefix. */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";
/** Most recently inserted findings first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";
/** Most recently updated findings first. */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// ---------------------------------------------------------------------------
// Family B — finding-groups (descending order = FAIL / critical / new first)
// ---------------------------------------------------------------------------

/** FAIL groups first. Descending integer-weighted order — minus prefix. */
export const FG_FAIL_FIRST = "-status";
/** Highest severity groups first. Descending order — minus prefix. */
export const FG_SEVERITY_HIGH_FIRST = "-severity";
/** New results first. Descending order — minus prefix. */
export const FG_DELTA_NEW_FIRST = "-delta";
/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family A (plain findings)
// ---------------------------------------------------------------------------

/**
 * Default ordering for the plain findings list. No `delta` — plain findings
 * do not expose that field — and no minus prefix on the ENUM columns.
 */
export const FINDINGS_DEFAULT_SORT = "status,severity,-inserted_at";
/**
 * Ordering used when the API call already applies a `filter[status]`, so the
 * `status` token is omitted.
 */
export const FINDINGS_FILTERED_SORT = "severity,-inserted_at";
/**
 * Ordering for the "other findings" list in the resource drawer. Uses
 * `updated_at` because the latest-findings endpoint exposes it.
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = "severity,-updated_at";

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family B (finding-groups)
// ---------------------------------------------------------------------------

/** Default ordering for the finding-groups list. */
export const FINDING_GROUPS_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/** Default ordering for a group's resources drill-down (same shape). */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT =
  "-status,-severity,-delta,-last_seen_at";
/**
 * Ordering used when the grouped API already applies a status filter. Omits
 * `status` and `delta`, and must NOT contain `inserted_at`, which is not a
 * valid sort parameter on the grouped API and causes a backend error.
 */
export const FINDING_GROUPS_FILTERED_SORT = "-severity,-last_seen_at";

// ---------------------------------------------------------------------------
// Composition helper
// ---------------------------------------------------------------------------

/**
 * Joins sort token strings with commas in the order given. The leftmost token
 * has the highest sort precedence (JSON:API rule). Returns an empty string
 * when called with no arguments.
 */
export function composeSort(...tokens: string[]): string {
  return tokens.join(",");
}
